// BTC: SOLO MQTT es la verdad del precio. Gana el timestamp mas nuevo. Rechaza outliers.
// Ademas guarda binance/coinbase por separado, sus edades, flujo/min y la senal LONG/SHORT.
let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || typeof p !== 'object') return null;

const price = Number(p.price);
if (!Number.isFinite(price) || price < 1000) return null;

// timestamp del propio mensaje si viene; si no, hora de llegada
let mt = Number(p.ts != null ? p.ts : (p.timestamp != null ? p.timestamp : (p.time != null ? p.time : (p.t != null ? p.t : p.epoch))));
if (!Number.isFinite(mt)) mt = Date.now();
else if (mt < 1e12) mt = mt * 1000;
const last = flow.get('btcMqttT') || 0;
if (mt < last) return null;                    // mensaje mas viejo -> ignorar

// filtro anti-outlier: rechazar saltos absurdos vs ultimo precio bueno (glitch del sensor)
const prevBtc = flow.get('btc') || {};
const lastP = Number(prevBtc.price);
const maxJump = Number(global.get('cryptoBtcMaxJump')) || 0.15;
if (Number.isFinite(lastP) && lastP > 0 && Math.abs(price - lastP) / lastP > maxJump) {
  node.status({ fill: 'yellow', shape: 'ring', text: 'BTC outlier ignorado: ' + price });
  return null;
}

flow.set('btcMqttT', mt);   // aceptado

const now = Date.now();
const flowv = Number(p.flow_btc_s);
const flowM = Number(p.flow_btc_m);
const rssi  = Number(p.rssi);

// precios por exchange (separados) + frescura de cada feed
const bin   = Number(p.binance);
const cb    = Number(p.coinbase);
const binAge = Number(p.binance_age_ms);
const cbAge  = Number(p.coinbase_age_ms);

// senal de trading del propio sensor
const sig    = (typeof p.signal === 'string') ? p.signal : null;
const sigSrc = (typeof p.signal_source === 'string') ? p.signal_source : null;
const sigN   = Number(p.signal_samples);

let samples = context.get('flowSamples') || [];
if (Number.isFinite(flowv)) samples.push({ t: now, v: flowv });
samples = samples.filter(s => s.t >= now - 300000);
context.set('flowSamples', samples);
let avg = null;
if (samples.length) avg = samples.reduce((a, s) => a + s.v, 0) / samples.length;

flow.set('btc', Object.assign({}, prevBtc, {
  price: price,
  binance:  Number.isFinite(bin) ? bin : (prevBtc.binance  != null ? prevBtc.binance  : null),
  coinbase: Number.isFinite(cb)  ? cb  : (prevBtc.coinbase != null ? prevBtc.coinbase : null),
  binAge:   Number.isFinite(binAge) ? binAge : null,
  cbAge:    Number.isFinite(cbAge)  ? cbAge  : null,
  flow:  Number.isFinite(flowv) ? flowv : null,
  flowM: Number.isFinite(flowM) ? flowM : null,
  avg:   avg,
  rssi:  Number.isFinite(rssi) ? rssi : null,
  device: p.device || '-',
  signal:    sig    || (prevBtc.signal    != null ? prevBtc.signal    : null),
  signalSrc: sigSrc || (prevBtc.signalSrc != null ? prevBtc.signalSrc : null),
  signalN:   Number.isFinite(sigN) ? sigN : (prevBtc.signalN != null ? prevBtc.signalN : null),
  ts: now, pxTs: now
}));
flow.set('mqttPxTs', now);

// tick real (precio compuesto) al grafico en vivo de BTC; binance/coinbase los dibuja el sampler 1s
return { payload: price, topic: 'BTC', lo: flow.get('lo_btc'), hi: flow.get('hi_btc') };

// Suscribe ticker+trade SOLO cuando el WS esta abierto (se dispara con mensajes entrantes).
// Kraken v2 manda 'status' al (re)conectar y 'heartbeat' seguido; ahi el socket esta abierto -> el send no falla.
let d; try { d = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; } catch (e) { return null; }
if (!d || !d.channel) return null;
const now = Date.now();
const lastSub = context.get('lastSub') || 0;
let doSub = false;
if (d.channel === 'status') doSub = true;                                   // (re)conexion
else if (d.channel === 'heartbeat' && (now - lastSub) > 60000) doSub = true; // fallback si no vino status
if (!doSub) return null;
context.set('lastSub', now);
const symbols = ['BTC/USD', 'XMR/USD', 'GMX/USD', 'LTC/USD'];
node.status({ fill: 'green', shape: 'dot', text: 'suscrito ' + new Date().toLocaleTimeString() });
return [[
  { payload: JSON.stringify({ method: 'subscribe', params: { channel: 'ticker', symbol: symbols } }) },
  { payload: JSON.stringify({ method: 'subscribe', params: { channel: 'trade',  symbol: symbols } }) }
]];

// Kraken WS v2: ticker + trade. BTC: NO se toca el precio (verdad = MQTT); solo enriquece vol/bid/ask
flow.set('krakenUp', Date.now());   // llego algo por el WS -> conexion viva
let d;
try { d = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; }
catch (e) { return null; }
if (!d || typeof d !== 'object') return null;

if (d.method === 'subscribe') {
  node.status({ fill: d.success ? 'green' : 'red', shape: 'dot',
    text: 'sub ' + ((d.result && d.result.channel) || '') + ' ' + (d.success ? 'ok' : 'err') });
  return null;
}
const chan = d.channel;
if (chan !== 'ticker' && chan !== 'trade') return null;
const list = Array.isArray(d.data) ? d.data : [];
const now = Date.now();
const SYM = { btc: 'BTC', xmr: 'XMR', gmx: 'GMX', ltc: 'LTC' };
function keyOf(sym) {
  sym = String(sym || '');
  return sym === 'BTC/USD' ? 'btc' : sym === 'XMR/USD' ? 'xmr' : sym === 'GMX/USD' ? 'gmx' : sym === 'LTC/USD' ? 'ltc' : null;
}
const live = { btc: null, xmr: null, gmx: null, ltc: null };

if (chan === 'ticker') {
  for (const t of list) {
    const key = keyOf(t.symbol);
    if (!key) continue;
    const price = Number(t.last);
    if (!Number.isFinite(price) || price <= 0) continue;
    const prev = flow.get(key) || {};
    const isBtc = (key === 'btc');
    if (!isBtc) {
      const pj = Number(prev.price);
      const mj = Number(global.get('cryptoAltMaxJump')) || Number(global.get('cryptoBtcMaxJump')) || 0.15;
      if (Number.isFinite(pj) && pj > 0 && Math.abs(price - pj) / pj > mj) { node.status({ fill: 'yellow', shape: 'ring', text: key.toUpperCase() + ' outlier ignorado ' + price }); continue; }
    }
    const upd = {
      bid: Number.isFinite(Number(t.bid)) ? Number(t.bid) : (prev.bid != null ? prev.bid : null),
      ask: Number.isFinite(Number(t.ask)) ? Number(t.ask) : (prev.ask != null ? prev.ask : null),
      vol24: Number.isFinite(Number(t.volume)) ? Number(t.volume) : prev.vol24,
      ts: now
    };
    if (!isBtc) { upd.price = price; upd.pxTs = now; }   // BTC nunca cambia precio por Kraken
    flow.set(key, Object.assign({}, prev, upd));
    flow.set('wslast_' + key, now);
    if (!isBtc) live[key] = { payload: price, topic: SYM[key], lo: flow.get('lo_' + key), hi: flow.get('hi_' + key) };
  }
} else if (chan === 'trade') {
  const byKey = {};
  for (const tr of list) {
    const key = keyOf(tr.symbol);
    if (!key) continue;
    const v = Number(tr.qty);
    if (!Number.isFinite(v)) continue;
    const s = tr.side === 'buy' ? 'b' : tr.side === 'sell' ? 's' : null;
    (byKey[key] = byKey[key] || []).push({ t: now, v: v, s: s });
  }
  for (const key of Object.keys(byKey)) {
    let arr = flow.get('trades_' + key) || [];
    arr = arr.concat(byKey[key]);
    arr = arr.filter(x => x.t >= now - 300000);
    if (arr.length > 3000) arr = arr.slice(-3000);
    flow.set('trades_' + key, arr);
  }
}
return [live.btc, live.xmr, live.gmx, live.ltc];

// Latido REST: precio + vol24. BTC: NO se toca el precio (verdad = MQTT)
const d = msg.payload;
if (!d || !d.result || (Array.isArray(d.error) && d.error.length)) {
  node.status({ fill: 'red', shape: 'ring', text: 'REST error' });
  return null;
}
const now = Date.now();
const res = d.result;
let n = 0;
for (const kk of Object.keys(res)) {
  const t = res[kk];
  if (!t || !t.c || !t.c.length) continue;
  const price = Number(t.c[0]);
  if (!Number.isFinite(price) || price <= 0) continue;
  const K = kk.toUpperCase();
  const key = K.indexOf('XBT') >= 0 ? 'btc' : K.indexOf('XMR') >= 0 ? 'xmr' : K.indexOf('GMX') >= 0 ? 'gmx' : K.indexOf('LTC') >= 0 ? 'ltc' : null;
  if (!key) continue;
  const prev = flow.get(key) || {};
  const isBtc = (key === 'btc');
  const upd = {
    bid: (t.b && t.b.length) ? Number(t.b[0]) : (prev.bid != null ? prev.bid : null),
    ask: (t.a && t.a.length) ? Number(t.a[0]) : (prev.ask != null ? prev.ask : null),
    vol24:    (t.v && t.v.length > 1) ? Number(t.v[1]) : prev.vol24,
    trades24: (t.t && t.t.length > 1) ? Number(t.t[1]) : prev.trades24,
    ts: now
  };
  if (!isBtc) { upd.price = price; upd.pxTs = now; }   // BTC nunca cambia precio por REST
  flow.set(key, Object.assign({}, prev, upd));
  n++;
}
node.status({ fill: 'green', shape: 'dot', text: 'REST ok ' + n + ' · ' + new Date(now).toLocaleTimeString() });
return null;

// Pide las operaciones recientes de cada par (REST Trades, para la presion)
const pairs = [['XBTUSD','btc'], ['XMRUSD','xmr'], ['GMXUSD','gmx'], ['LTCUSD','ltc']];
const out = [];
for (const [p, key] of pairs) {
  const since = flow.get('tradesSince_' + key);
  let url = 'https://api.kraken.com/0/public/Trades?pair=' + p + '&count=1000';
  if (since) url += '&since=' + since;
  out.push({ url: url, coin: key });
}
return [out];

// Parsea REST Trades -> rellena trades_<coin> (compra/venta) para la presion
const d = msg.payload;
const key = msg.coin;
if (!d || !d.result || !key) return null;
if (Array.isArray(d.error) && d.error.length) { node.status({fill:'red',shape:'ring',text:'trades err'}); return null; }
const res = d.result;
const now = Date.now();

let list = null;
for (const kk of Object.keys(res)) { if (kk !== 'last') { list = res[kk]; break; } }

if (Array.isArray(list)) {
  let arr = flow.get('trades_' + key) || [];
  for (const tr of list) {
    const v = Number(tr[1]);
    const tsec = Number(tr[2]);
    const s = tr[3];                 // 'b' compra / 's' venta
    if (Number.isFinite(v) && Number.isFinite(tsec)) arr.push({ t: tsec * 1000, v: v, s: s });
  }
  arr = arr.filter(x => x.t >= now - 300000);   // ventana 5 min
  if (arr.length > 5000) arr = arr.slice(-5000);
  flow.set('trades_' + key, arr);
}
if (res.last) flow.set('tradesSince_' + key, res.last);
return null;

// Cada 5 s: panel resumen + tarjetas con min/max, EMA, D, vol, presion y break-even
// BTC ademas: binance/coinbase por separado, spread, edades y senal LONG/SHORT.
const now = Date.now();
const staleMs = (Number(global.get('cryptoStaleSec')) || 600) * 1000;
const bmap = global.get('cryptoBreakeven') || {};

const ringOf = k => flow.get('hist_' + k) || [];

function chgWin(k, price, ms) {
  const ring = ringOf(k);
  if (!ring.length) return null;
  const target = now - ms;
  let ref = ring[0];
  for (const pt of ring) { if (pt.t <= target) ref = pt; else break; }
  if (!ref || !Number.isFinite(ref.p) || ref.p === 0) return null;
  return (price - ref.p) / ref.p * 100;
}
function hilo(k, price) {
  const ring = ringOf(k);
  const ps = [];
  for (const pt of ring) { const v = Number(pt.p); if (Number.isFinite(v) && v > 0) ps.push(v); }
  if (Number.isFinite(price) && price > 0) ps.push(price);
  if (!ps.length) return { hi: null, lo: null, pos: 50 };
  ps.sort((a, b) => a - b);
  const pick = q => ps[Math.min(ps.length - 1, Math.max(0, Math.round(q * (ps.length - 1))))];
  let lo, hi;
  if (ps.length >= 25) { lo = pick(0.02); hi = pick(0.98); }   // percentiles => ignora ticks glitcheados aislados
  else { lo = ps[0]; hi = ps[ps.length - 1]; }
  let pos = 50;
  if (hi > lo && Number.isFinite(price)) pos = (price - lo) / (hi - lo) * 100;
  return { hi: hi, lo: lo, pos: Math.max(0, Math.min(100, pos)) };
}
function pressure(k) {
  const arr = flow.get('trades_' + k) || [];
  let b = 0, s = 0;
  for (const x of arr) { if (x.s === 'b') b += x.v; else if (x.s === 's') s += x.v; }
  const tot = b + s;
  return tot > 0 ? { buy: b, sell: s, buyPct: b / tot * 100 } : { buy: 0, sell: 0, buyPct: null };
}

const map = [['btc','BTC'], ['xmr','XMR'], ['gmx','GMX'], ['ltc','LTC'], ['zec','ZEC']];
const decs = { btc: 2, xmr: 2, gmx: 3, ltc: 2, zec: 2 };
const cols = { btc: '#f2a900', xmr: '#ff6600', gmx: '#3fb950', ltc: '#c0c0c0', zec: '#f4b728' };
const sum = {}, cards = {};
for (const [k, sym] of map) {
  const q = flow.get(k);
  if (q && Number.isFinite(q.price)) {
    const hl = hilo(k, q.price);
    const _ring = ringOf(k);
    if (_ring.length) { const _n = Math.min(20, _ring.length); let _sm = 0; for (let _i = _ring.length - _n; _i < _ring.length; _i++) _sm += _ring[_i].p; flow.set('avg_' + k, _sm / _n); }
    const pr = pressure(k);
    const beRaw = Number(bmap[k]);
    const be = (Number.isFinite(beRaw) && beRaw > 0) ? beRaw : null;
    const bin = Number(q.binance), cb = Number(q.coinbase);
    const hasXch = Number.isFinite(bin) && Number.isFinite(cb);
    const item = {
      symbol: sym, price: q.price, dec: decs[k], color: cols[k],
      be: be,
      bePct:  be ? (q.price - be) / be * 100 : null,       // signo: + arriba / - abajo del BE
      beRise: be ? (be - q.price) / q.price * 100 : null,   // cuanto debe subir para llegar
      change:   chgWin(k, q.price, 3600000),
      change24: chgWin(k, q.price, 86400000),
      hi: hl.hi, lo: hl.lo, pos: hl.pos,
      age:   q.ts ? Math.round((now - q.ts) / 1000) : null,
      stale: q.ts ? (now - q.ts > staleMs) : true,
      bid: q.bid != null ? q.bid : null,
      ask: q.ask != null ? q.ask : null,
      vol24:    q.vol24    != null ? q.vol24    : null,
      trades24: q.trades24 != null ? q.trades24 : null,
      flow: q.flow != null ? q.flow : null,
      flowM: q.flowM != null ? q.flowM : null,
      avg:  q.avg  != null ? q.avg  : null,
      rssi: q.rssi != null ? q.rssi : null,
      device: q.device || null,
      buyPct: (pr.buyPct != null ? pr.buyPct : (q.buyPct != null ? q.buyPct : null)),
      buy: (pr.buyPct != null ? pr.buy : (q.buy != null ? q.buy : 0)),
      sell: (pr.buyPct != null ? pr.sell : (q.sell != null ? q.sell : 0)),
      // --- exchanges separados (BTC) ---
      binance:  Number.isFinite(bin) ? bin : null,
      coinbase: Number.isFinite(cb)  ? cb  : null,
      binAge:   q.binAge != null ? q.binAge : null,
      cbAge:    q.cbAge  != null ? q.cbAge  : null,
      spread:    hasXch ? (cb - bin) : null,
      spreadPct: hasXch && bin > 0 ? (cb - bin) / bin * 100 : null,
      signal:    q.signal    != null ? q.signal    : null,
      signalSrc: q.signalSrc != null ? q.signalSrc : null,
      signalN:   q.signalN   != null ? q.signalN   : null
    };
    sum[k] = item; cards[k] = { payload: item };
  } else { sum[k] = null; cards[k] = null; }
}
flow.set('cardsSummary', sum); global.set('cardsSummary', sum);
return [{ payload: sum }, cards.btc, cards.xmr, cards.gmx, cards.ltc, cards.zec];

// Cada 1 s: precio + margen fijo por moneda (series invisibles _lo/_hi).
// BTC: ademas dibuja Binance y Coinbase como lineas propias y ensancha el margen para que entren.
const now = Date.now();
const staleMs = (Number(global.get('cryptoStaleSec')) || 600) * 1000;
const winMs = 120000; // 2 min
const padFloor = { btc: 0.08, xmr: 0.01, gmx: 0.003, ltc: 0.008 };  // margen MINIMO (USD) por moneda; editable

function make(k, sym) {
  const q = flow.get(k);
  if (!q || !Number.isFinite(q.price)) return null;
  if (q.ts && (now - q.ts) > staleMs) return null;
  const price = q.price;

  let r = flow.get('live_' + k) || [];
  r.push({ t: now, p: price });
  r = r.filter(x => x.t >= now - winMs);
  flow.set('live_' + k, r);

  let lo = price, hi = price;
  for (const x of r) { if (x.p < lo) lo = x.p; if (x.p > hi) hi = x.p; }

  // BTC: lineas de exchange + incluirlas en el min/max del margen
  const extra = [];
  if (k === 'btc') {
    const bin = Number(q.binance), cb = Number(q.coinbase);
    if (Number.isFinite(bin)) { if (bin < lo) lo = bin; if (bin > hi) hi = bin; extra.push({ payload: bin, topic: 'Binance' }); }
    if (Number.isFinite(cb))  { if (cb  < lo) lo = cb;  if (cb  > hi) hi = cb;  extra.push({ payload: cb,  topic: 'Coinbase' }); }
  }

  const range = hi - lo;                       // rango real de la ventana (incluye binance/coinbase en BTC)
  const pad = Math.max(range * 0.06, padFloor[k] || (price * 0.00008)); // margen ceñido: 6% del rango real + piso chico

  return [
    { payload: price,    topic: sym, lo: flow.get('lo_' + k), hi: flow.get('hi_' + k) }
  ].concat(extra, [
    { payload: lo - pad, topic: sym + ' _lo' },
    { payload: hi + pad, topic: sym + ' _hi' }
  ]);
}
return [make('btc','BTC'), make('xmr','XMR'), make('gmx','GMX'), make('ltc','LTC')];

// Cada 1 min: precio + EMA lenta + EMA rapida (+ break-even), corta linea en huecos, append a disco
const now = Date.now();
const base = global.get('cryptoHistBase') || 'cryptohist/';
const Ns = Number(global.get('cryptoEmaN')) || 20;
const Nf = Number(global.get('cryptoEmaFast')) || 9;
const ks = 2 / (Ns + 1), kf = 2 / (Nf + 1);
const bmap = global.get('cryptoBreakeven') || {};
const gapMs = (Number(global.get('cryptoGapMin')) || 10) * 60000;
const map = [['btc','BTC'], ['xmr','XMR'], ['gmx','GMX'], ['ltc','LTC'], ['zec','ZEC']];

const files = [];
const charts = { btc: null, xmr: null, gmx: null, ltc: null };

for (const [k, sym] of map) {
  const q = flow.get(k);
  if (!q || !Number.isFinite(q.price)) continue;
  if (q.ts && (now - q.ts) > 120000) continue;
  const p = q.price;

  let ring = flow.get('hist_' + k) || [];
  const prevT = ring.length ? ring[ring.length - 1].t : null;
  const gap = (prevT != null) && ((now - prevT) > gapMs);
  ring.push({ t: now, p: p });
  const cut = now - 86400000;
  ring = ring.filter(r => r.t >= cut);
  if (ring.length > 1500) ring = ring.slice(-1500);
  flow.set('hist_' + k, ring);

  let es = flow.get('ema_' + k), ef = flow.get('emaf_' + k);
  if (gap) { es = null; ef = null; }
  es = (es == null) ? p : (p * ks + es * (1 - ks));
  ef = (ef == null) ? p : (p * kf + ef * (1 - kf));
  flow.set('ema_' + k, es);
  flow.set('emaf_' + k, ef);

  const out = [];
  if (gap) {
    out.push({ payload: null, topic: sym });
    out.push({ payload: null, topic: sym + ' EMA' });
    out.push({ payload: null, topic: sym + ' EMA9' });
  }
  out.push({ payload: p,  topic: sym });
  out.push({ payload: es, topic: sym + ' EMA' });
  out.push({ payload: ef, topic: sym + ' EMA9' });
  const beRaw = Number(bmap[k]);
  if (Number.isFinite(beRaw) && beRaw > 0) out.push({ payload: beRaw, topic: sym + ' BE' });

  files.push({ filename: base + sym + '.log', payload: JSON.stringify({ t: now, p: p }) });
  charts[k] = out;
}

return [files, null, null, null, null];  // los graficos los redibuja el seeder (con linea de precio actual)

// Pide leer el historial de cada moneda (una vez al arrancar)
const base = global.get('cryptoHistBase') || 'cryptohist/';
return [ ['BTC','XMR','GMX','LTC','ZEC'].map(sym => ({ filename: base + sym + '.log', coin: sym })) ];

// Siembra: precio + EMA lenta + EMA rapida (+ break-even), cortando en huecos
const coin = msg.coin || '?';
let txt = msg.payload;
if (Buffer.isBuffer(txt)) txt = txt.toString('utf8');
if (typeof txt !== 'string' || !txt.length) return null;

const now = Date.now();
const days = Number(global.get('cryptoViewDays')) || 3;
const cut = now - days * 86400000;
const gapMs = (Number(global.get('cryptoGapMin')) || 10) * 60000;

const pts = [];
for (const ln of txt.split(/\r?\n/)) {
  if (!ln) continue;
  let o; try { o = JSON.parse(ln); } catch (e) { continue; }
  if (!o || !Number.isFinite(o.t) || !Number.isFinite(o.p)) continue;
  if (o.t < cut) continue;
  pts.push({ x: o.t, y: o.p });
}
if (!pts.length) return null;
pts.sort((a, b) => a.x - b.x);
let _lo = pts[0].y, _hi = pts[0].y;
for (let _i = 0; _i < pts.length; _i++) { const _y = pts[_i].y; if (_y < _lo) _lo = _y; if (_y > _hi) _hi = _y; }
flow.set('lo_' + coin.toLowerCase(), _lo); flow.set('hi_' + coin.toLowerCase(), _hi);

const Ns = Number(global.get('cryptoEmaN')) || 20;
const Nf = Number(global.get('cryptoEmaFast')) || 9;
const ks = 2 / (Ns + 1), kf = 2 / (Nf + 1);
let es = null, ef = null;
const esPts = [], efPts = [];
for (let i = 0; i < pts.length; i++) {
  if (i > 0 && (pts[i].x - pts[i-1].x) > gapMs) { es = null; ef = null; }
  es = (es == null) ? pts[i].y : (pts[i].y * ks + es * (1 - ks));
